    n = data[0]
    y = [0] * (n + 2)
    y[0] = n + 1
    for k in range(n):
        x, v = data[2*k+1:2*k+3]
        y[x] = v
    dp = [0] * (n + 2)
    dp[0] = 1
    for a in range(n + 1):
        if not dp[a]:
            continue
        hi = y[a]
