            lo = y[b]
            if lo >= hi:
                continue
            vals = []
            mins = []
            mn = n + 1
            for k in range(a + 1, b):
                v = y[k]
                if lo < v < hi:
                    vals.append(v)
                    mins.append(mn)
                    if v < mn:
                        mn = v
            mx = 0
            good = True
            for k in range(len(vals) - 1, -1, -1):
                v = vals[k]
                if mx < v < mins[k]:
                    good = False
                    break
                if v > mx:
                    mx = v
            if good:
                dp[b] = (dp[b] + dp[a]) % MOD
    print(dp[n + 1])

