def brute(p):
 n=len(p); masks=[sum(1<<j for j in range(n) if (i-j)*(p[i]-p[j])>0) for i in range(n)]
 seen={(1<<n)-1}; todo=list(seen)
 for s in todo:
  for i in range(n):
   if s>>i&1:
    t=s&~masks[i]
    if t not in seen:seen.add(t);todo.append(t)
 return len(seen)
