import sys
from collections import deque

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [v - 1 for v in data[2:]]
    indeg = [0] * n
    for v in a:
        indeg[v] += 1

    q = deque(i for i in range(n) if indeg[i] == 0)
    dp = [None] * n
    while q:
        v = q.popleft()
        cur = dp[v]
        dp[v] = None
        if cur is None:
            cur = list(range(1, m + 1))
        else:
            s = 0
            for k in range(m):
                s = (s + cur[k]) % MOD
                cur[k] = s
        p = a[v]
        dest = dp[p]
        if dest is None:
            dp[p] = cur
        else:
            for k in range(m):
                dest[k] = dest[k] * cur[k] % MOD
        indeg[p] -= 1
        if indeg[p] == 0:
            q.append(p)

    ans = 1
    for i in range(n):
        if indeg[i] == 0:
            continue
        cur = None
        v = i
        while indeg[v]:
            indeg[v] = 0
            other = dp[v]
            dp[v] = None
            if other is not None:
                if cur is None:
                    cur = other
                else:
                    for k in range(m):
                        cur[k] = cur[k] * other[k] % MOD
            v = a[v]
        ways = m if cur is None else sum(cur) % MOD
        ans = ans * ways % MOD
    print(ans)


if __name__ == '__main__':
    main()

