import sys

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    factors = {}
    for i, x in enumerate(data[1:]):
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                if p not in factors:
                    factors[p] = [0] * (n - 1)
                factors[p][i] = e
            p += 1
        if x > 1:
            if x not in factors:
                factors[x] = [0] * (n - 1)
            factors[x][i] = 1

    answer = 1
    for p, exponents in factors.items():
        total = sum(exponents)
        powers = [1] * (total + 1)
        for j in range(total):
            powers[j + 1] = powers[j] * p % MOD

        # Normalize each prefix so that its minimum exponent is zero.
        # dp[h] sums products for prefixes ending at exponent h.
        dp = [1]
        for i, e in enumerate(exponents, 1):
            if e == 0:
                dp = [v * powers[h] % MOD for h, v in enumerate(dp)]
                continue

            nd = [0] * (len(dp) + e)
            for h, v in enumerate(dp):
                nd[h + e] = v * powers[h + e] % MOD

            # A downward step below zero raises all i previous exponents.
            z = 0
            for h in range(min(e, len(dp))):
                z += dp[h] * pow(p, i * (e - h), MOD)
            nd[0] = z % MOD

            for h in range(e, len(dp)):
                k = h - e
                nd[k] = (nd[k] + dp[h] * powers[k]) % MOD
            dp = nd

        answer = answer * (sum(dp) % MOD) % MOD

    print(answer)


if __name__ == '__main__':
    main()

