from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        buckets = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            buckets[b].append((a, i))

        gains = [0] * len(conflictingPairs)
        largest = second = 0
        owner = -1
        baseline = 0

        for r in range(1, n + 1):
            for a, i in buckets[r]:
                if a > largest:
                    second = largest
                    largest = a
                    owner = i
                elif a > second:
                    second = a

            baseline += r - largest
            if owner != -1:
                gains[owner] += largest - second

        return baseline + max(gains)

