import sys


def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    m = next(it)
    q = next(it)
    edges = [(next(it) - 1, next(it) - 1, next(it)) for _ in range(m)]
    closed = [False] * m
    queries = []
    for _ in range(q):
        t = next(it)
        if t == 1:
            e = next(it) - 1
            closed[e] = True
            queries.append((1, e, 0))
        else:
            queries.append((2, next(it) - 1, next(it) - 1))

    inf = 10**18
    d = [[inf] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for e, (a, b, w) in enumerate(edges):
        if not closed[e]:
            d[a][b] = d[b][a] = w

    rn = range(n)
    for k in rn:
        dk = d[k]
        for i in rn:
            di = d[i]
            base = di[k]
            if base == inf:
                continue
            for j in rn:
                v = base + dk[j]
                if v < di[j]:
                    di[j] = v

    ans = []
    for t, a, b in reversed(queries):
        if t == 2:
            v = d[a][b]
            ans.append(str(v if v < inf else -1))
        else:
            a, b, w = edges[a]
            if w >= d[a][b]:
                continue
            da = d[a][:]
            db = d[b][:]
            for i in rn:
                if da[i] + w < db[i]:
                    base = da[i] + w
                    other = db
                elif db[i] + w < da[i]:
                    base = db[i] + w
                    other = da
                else:
                    continue
                di = d[i]
                for j in range(i + 1, n):
                    v = base + other[j]
                    if v < di[j]:
                        di[j] = v
                        d[j][i] = v

    sys.stdout.write('\n'.join(reversed(ans)))


if __name__ == '__main__':
    main()

