import random

def brute(a,m):
 @lru_cache(None)
 def f(r,mask):
  best=10**9
  for i,x in enumerate(r):
   if x:
    s=list(r);s[i]-=1
    z=1+f(tuple(sorted(s)),mask)
   else:
    z=0
    for j,(v,p) in enumerate(a):
     if mask>>j&1:
      s=list(r);s[i]=v-1
      z=max(z,1-p+f(tuple(sorted(s)),mask^(1<<j)))
   best=min(best,z)
  return best
