import sys
from math import gcd


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, budget = data[:2]
    machines = []
    upper = 10**9
    for i in range(n):
        a, p, b, q = data[2 + 4*i:6 + 4*i]
        # Make the first type at least as cost-efficient as the second.
        if p*b > q*a:
            a, p, b, q = b, q, a, p
        upper = min(upper, budget*a//p)
        # This many second-type machines can be replaced by first-type
        # machines with equal capacity and no greater cost.
        machines.append((a, p, b, q, a//gcd(a, b)))

    def feasible(w):
        total = 0
        for a, p, b, q, limit in machines:
            best = ((w+a-1)//a)*p
            for t in range(1, min(limit-1, (w+b-1)//b)+1):
                remaining = w-t*b
                cost = t*q
                if remaining > 0:
                    cost += ((remaining+a-1)//a)*p
                if cost < best:
                    best = cost
            total += best
            if total > budget:
                return False
        return True

    lo, hi = 0, upper+1
    while hi-lo > 1:
        mid = (lo+hi)//2
        if feasible(mid):
            lo = mid
        else:
            hi = mid
    print(lo)


if __name__ == '__main__':
    main()

