class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        m = len(s)
        steps = [0] * (m + 1)
        for w in range(2, m + 1):
            steps[w] = 1 + steps[w.bit_count()]
        good = [w for w in range(1, m + 1) if steps[w] < k]

        fact = [1] * (m + 1)
        for i in range(1, m + 1):
            fact[i] = fact[i - 1] * i % MOD
        invfact = [1] * (m + 1)
        invfact[m] = pow(fact[m], MOD - 2, MOD)
        for i in range(m, 0, -1):
            invfact[i - 1] = invfact[i] * i % MOD

        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = m - i - 1
                for w in good:
                    needed = w - prefix_ones
                    if needed < 0:
                        continue
                    if needed > remaining:
                        break
                    answer += fact[remaining] * invfact[needed] % MOD * invfact[remaining - needed] % MOD
                answer %= MOD
                prefix_ones += 1
        return answer

