import sys


def best(offsets, carry0=0, carry1=0):
    # carry0/carry1 count mountains determined by the next shift bit.
    if len(offsets) <= 1:
        return max(carry0, carry1) + len(offsets)

    even = []
    odd = []
    counts = [0, 0, 0, 0]
    for a in offsets:
        counts[a & 3] += 1
        if a & 1:
            odd.append((a + 1) // 2)
        else:
            even.append(a // 2)

    return max(
        carry0 + best(even, counts[3], counts[1]),
        carry1 + best(odd, counts[2], counts[0]),
    )


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    print(best(data[1:]))


if __name__ == '__main__':
    main()

