import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    rows = [0] * n
    for i in range(m):
        u, v = data[2 + 2 * i] - 1, data[3 + 2 * i] - 1
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduced row echelon form of the adjacency matrix over GF(2).
    pivots = []
    rank = 0
    for col in range(n):
        pivot = -1
        for i in range(rank, n):
            if (rows[i] >> col) & 1:
                pivot = i
                break
        if pivot == -1:
            continue
        rows[rank], rows[pivot] = rows[pivot], rows[rank]
        for i in range(n):
            if i != rank and (rows[i] >> col) & 1:
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    # Give each kernel basis vector its own bit position.
    pivot_set = set(pivots)
    answer = [0] * n
    bit = 0
    for col in range(n):
        if col in pivot_set:
            continue
        answer[col] |= 1 << bit
        for i, p in enumerate(pivots):
            if (rows[i] >> col) & 1:
                answer[p] |= 1 << bit
        bit += 1

    if any(x == 0 for x in answer):
        print('No')
    else:
        print('Yes')
        print(*answer)


if __name__ == '__main__':
    main()

