import sys

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m, k = data[:3]
    x = data[3:]
    changes = sum(x[i] != x[i + 1] for i in range(m - 1))

    remaining = n - (m * k - 1 + changes)
    if remaining < 0:
        print(0)
        return

    dp = [0] * (remaining + 1)
    dp[0] = 1

    # Multiply by product (1 - j*t)^(-m), 1 <= j < k.
    for j in range(1, k):
        for _ in range(m):
            for length in range(1, remaining + 1):
                dp[length] = (dp[length] + j * dp[length - 1]) % MOD

    # Every change between consecutive elements contributes another factor.
    if k > 2:
        for _ in range(changes):
            for length in range(1, remaining + 1):
                dp[length] = (dp[length] + (k - 2) * dp[length - 1]) % MOD

    factorial = 1
    for j in range(1, k):
        factorial = factorial * j % MOD

    print(dp[remaining] * pow(factorial, m, MOD) % MOD)


