from math import gcd

class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        powers = [1 % k] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k
        m = (n + 1) // 2
        weights = [0] * m
        for i in range(m):
            j = n - 1 - i
            weights[i] = (powers[i] + powers[j]) % k if i != j else powers[i]
        suffix = [k] * (m + 1)
        for i in range(m - 1, -1, -1):
            suffix[i] = gcd(suffix[i + 1], weights[i])
        half = []
        remainder = 0
        for i, w in enumerate(weights):
            for d in range(9, -1 if i else 0, -1):
                new_remainder = (remainder + d * w) % k
                if new_remainder % suffix[i + 1] == 0:
                    half.append(str(d))
                    remainder = new_remainder
                    break
        left = ''.join(half)
        return left + (left[:-1] if n % 2 else left)[::-1]

