def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    k = next(it)
    counts = [0] * 2500
    for _ in range(n):
        a = next(it)
        b = next(it)
        counts[(a - 1) * 50 + b - 1] += 1

    functions = [
        (i // 50 + 1, i % 50 + 1, min(count, k))
        for i, count in enumerate(counts) if count
    ]
    # Order from the innermost function to the outermost function.
    functions.sort(key=cmp_to_key(
        lambda f, g: (f[0] - 1) * g[1] - (g[0] - 1) * f[1]
    ))

    dp = [-1] * (k + 1)
    dp[0] = 1
    seen = 0
    for a, b, count in functions:
        for _ in range(count):
            seen += 1
            for j in range(min(seen, k), 0, -1):
                if dp[j - 1] != -1:
                    value = a * dp[j - 1] + b
                    if value > dp[j]:
                        dp[j] = value
    print(dp[k])

