import sys

MOD = 998244353


def solve():
    data = sys.stdin.buffer
    t = int(data.readline())
    out = []
    for _ in range(t):
        h, w = map(int, data.readline().split())
        parent = [-1] * (h + w)
        diff = bytearray(h + w)
        col = bytearray(w)
        components = h + w
        valid = True

        def find(x):
            parity = 0
            while parent[x] >= 0:
                y = parent[x]
                if parent[y] >= 0:
                    diff[x] ^= diff[y]
                    parent[x] = parent[y]
                parity ^= diff[x]
                x = parent[x]
            return x, parity

        for i in range(h):
            s = data.readline().strip()
            if not valid:
                continue
            row = 0
            for j, c in enumerate(s):
                if c == 65:
                    row ^= 1
                    col[j] ^= 1
                else:
                    a, pa = find(i)
                    b, pb = find(h + j)
                    parity = 1 ^ row ^ col[j] ^ pa ^ pb
                    if a == b:
                        if parity:
                            valid = False
                            break
                    else:
                        if parent[a] > parent[b]:
                            a, b = b, a
                        parent[a] += parent[b]
                        parent[b] = a
                        diff[b] = parity
                        components -= 1
            if row:
                valid = False
        if any(col):
            valid = False
        out.append(str(pow(2, components, MOD) if valid else 0))
    sys.stdout.write('\n'.join(out))


if __name__ == '__main__':
    solve()

