import sys


def solve(n, a, b):
    if a == b:
        return 0
    ap = [i for i, c in enumerate(a) if c == 49]
    bp = [i for i, c in enumerate(b) if c == 49]
    na = len(ap)
    nb = len(bp)
    if nb > na:
        return -1
    if nb == 1:
        return max(bp[0] - ap[0], ap[-1] - bp[0])

    runs = []
    i = 0
    while i < n:
        if a[i] == 49:
            i += 1
        else:
            j = i
            i = a.find(b'1', i)
            if i < 0:
                i = n
            runs.append((j, i))
    nr = len(runs)
    gaps = [bp[i + 1] - bp[i] - 1 for i in range(nb - 1)]
    first = ap[0]
    last = ap[-1]
    bf = bp[0]
    bl = bp[-1]

    def ok(k):
        s = bf - k
        if s > first:
            return False
        p = z = 0
        for g in gaps:
            while p < na and ap[p] < s:
                p += 1
            if p == na:
                return False
            v = ap[p]
            s = v + ((v - s) & 1) + 1
            if g:
                while z < nr:
                    l, r = runs[z]
                    v = l if l > s else s
                    v += (v - s) & 1
                    if v + g <= r:
                        s = v + g
                        break
                    z += 1
                else:
                    return False
        while p < na and ap[p] < s:
            p += 1
        if p == na:
            return False
        return last + ((last - s) & 1) <= bl + k

    best = 2 * n + 2
    for parity in (0, 1):
        hi = (min(2 * n + 1, best - 1) - parity) // 2
        if hi < 0 or not ok(2 * hi + parity):
            continue
        lo = -1
        while hi - lo > 1:
            mid = (lo + hi) // 2
            if ok(2 * mid + parity):
                hi = mid
            else:
                lo = mid
        best = 2 * hi + parity
    return best if best <= 2 * n + 1 else -1


def main():
    data = sys.stdin.buffer.read().split()
    t = int(data[0])
    out = []
    for j in range(t):
        n = int(data[3 * j + 1])
        a = data[3 * j + 2]
        b = data[3 * j + 3]
        out.append(str(solve(n, a, b)))
    sys.stdout.write('\n'.join(out))


