import heapq


def convolution(a, g):
    n = len(a)
    limit = len(g) - 1
    result = [0] * n

    def solve(lo, hi, left, right):
        if lo > hi:
            return
        mid = (lo + hi) // 2
        start = max(left, mid - limit)
        end = min(mid, right)
        best = -1
        opt = start
        for t in range(start, end + 1):
            value = a[t] + g[mid - t]
            if value > best:
                best = value
                opt = t
        result[mid] = best
        solve(lo, mid - 1, left, opt)
        solve(mid + 1, hi, opt, right)

    solve(0, n - 1, 0, n - 1)
    return result


def main():
