    groups = [[] for _ in range(W + 1)]
    for i in range(2, len(data), 2):
        w, v = data[i], data[i + 1]
        if v > 1:
            groups[w].append(1 - v)

    dp = [0] * (W + 1)
    for w in range(1, W + 1):
        heap = groups[w]
        if not heap:
            continue
        heapq.heapify(heap)
        g = [0]
        for _ in range(W // w):
            value = -heap[0]
            if value <= 0:
                break
            g.append(g[-1] + value)
            heapq.heapreplace(heap, 2 - value)

        count = len(g) - 1
        if count >= 16:
            ndp = [0] * (W + 1)
            for r in range(w):
