from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        start = [0] * n
        end = [0] * n
        order = []
        stack = [0]
        while stack:
            v = stack.pop()
            if v >= 0:
                start[v] = len(order)
                stack.append(~v)
                stack.extend(reversed(children[v]))
            else:
                v = ~v
                order.append(s[v])
                end[v] = len(order)

        text = '#' + '#'.join(order) + '#'
        m = len(text)
        radius = [0] * m
        center = right = 0
        for i in range(m):
            k = min(right - i, radius[2 * center - i]) if i < right else 0
            while i - k - 1 >= 0 and i + k + 1 < m and text[i - k - 1] == text[i + k + 1]:
                k += 1
            radius[i] = k
            if i + k > right:
                center, right = i, i + k

        return [radius[start[v] + end[v]] >= end[v] - start[v] for v in range(n)]

