class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        mod = 10**9 + 7
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - 97] += 1
        head = 0
        for _ in range(t):
            head = (head - 1) % 26
            nxt = (head + 1) % 26
            counts[nxt] = (counts[nxt] + counts[head]) % mod
        return sum(counts) % mod

