from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        s = bytes(nums)
        n = len(s)
        z = [0] * n
        left = right = 0
        for k in range(1, n):
            v = min(right - k + 1, z[k - left]) if k <= right else 0
            while k + v < n and s[v] == s[k + v]:
                v += 1
            z[k] = v
            if k + v - 1 > right:
                left, right = k, k + v - 1

        answer = 0
        for i in range(1, n - 1):
            length = n - i
            limit = length // 2
            if z[i] >= i:
                answer += max(0, n - 2 * i)
                limit = min(limit, i - 1)
            if not limit:
                continue

            t = s[i:]
            zz = [0] * (limit + 1)
            left = right = 0
            for k in range(1, limit + 1):
                v = min(right - k + 1, zz[k - left]) if k <= right else 0
                while k + v < length and t[v] == t[k + v]:
                    v += 1
                zz[k] = v
                if k + v - 1 > right:
                    left, right = k, k + v - 1
                if v >= k:
                    answer += 1
        return answer

