from itertools import groupby

class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        zeros = [sum(1 for _ in group) for char, group in groupby(s) if char == '0']
        gain = max((zeros[i - 1] + zeros[i] for i in range(1, len(zeros))), default=0)
        return s.count('1') + gain

