class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        def at_least(limit):
            counts = dict.fromkeys('aeiou', 0)
            distinct = consonants = left = total = 0
            for right, ch in enumerate(word):
                if ch in counts:
                    if counts[ch] == 0:
                        distinct += 1
                    counts[ch] += 1
                else:
                    consonants += 1
                while distinct == 5 and consonants >= limit:
                    total += len(word) - right
                    old = word[left]
                    if old in counts:
                        counts[old] -= 1
                        if counts[old] == 0:
                            distinct -= 1
                    else:
                        consonants -= 1
                    left += 1
            return total
        return at_least(k) - at_least(k + 1)

